package net.civeira.phylax.feature.observe.observeddashboard.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observeddashboard.domain.ObservedDashboard;
import net.civeira.phylax.feature.observe.observeddashboard.domain.valueobject.NameVO;

class NameValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of name of observed dashboard")
  void test_name_value_holder_assign_plain_value() {
    Object holder = new Object();
    NameValueHolder<Object> value = new NameValueHolder<>(holder);
    Assertions.assertSame(holder, value.name("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getNameValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getName().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of name of observed dashboard")
  void test_name_value_holder_assign_value_object() {
    Object holder = new Object();
    NameValueHolder<Object> value = new NameValueHolder<>(holder);
    NameVO vo = NameVO.from("one");
    Assertions.assertFalse(value.getNameValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.name(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getNameValue().orElseThrow());
    Assertions.assertSame(holder, value.name(Optional.empty()));
    Assertions.assertFalse(value.getNameValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.name(Optional.of(vo)));
    Assertions.assertSame(vo, value.getNameValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of name of observed dashboard against the original")
  void test_name_value_holder_read() {
    Object holder = new Object();
    NameValueHolder<Object> value = new NameValueHolder<>(holder);
    NameVO vo = NameVO.from("one");
    NameVO other = NameVO.from("one");
    ObservedDashboard original = Mockito.mock(ObservedDashboard.class);
    Mockito.when(original.getNameValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readName(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readName(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.name(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readName(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readName(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of name of observed dashboard")
  void test_name_value_holder_unset() {
    Object holder = new Object();
    NameValueHolder<Object> value = new NameValueHolder<>(holder);
    NameVO vo = NameVO.from("one");
    value.name(vo);
    Assertions.assertSame(holder, value.unsetNameIfMatches("name_other"));
    Assertions.assertTrue(value.getNameValue().isPresent(), "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetNameIfMatches("name"));
    Assertions.assertFalse(value.getNameValue().isPresent(), "The field name must clear the value");
    value.name(vo);
    Assertions.assertSame(holder, value.unsetName());
    Assertions.assertFalse(value.getNameValue().isPresent(), "Unset must clear the value");
  }
}
